class Solution(object):
    def getMoneyAmount(self, n):
        """
        :type n: int
        :rtype: int
        """
        dp = [[0 for _ in range(n + 1)] for _ in range(n + 1)]
        for j in range(1, n):
            for i in range(1, n - j + 1):
                dp[i][i + j] = float("inf")
                for k in range(i, i + j):
                    dp[i][i + j] = min(dp[i][i + j], max(dp[i][k - 1], dp[k + 1][i + j]) + k)
        return dp[1][n]
